CREATE OR REPLACE FUNCTION rticore_raise(msg text) RETURNS text LANGUAGE plpgsql VOLATILE AS $f$
BEGIN RAISE EXCEPTION USING MESSAGE = msg, ERRCODE = 'P0001'; END $f$;
