-- rticore_ap_review: BEFORE UPDATE ON rticore_ap_supplier_invoices
CREATE OR REPLACE FUNCTION rticore_ap_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN OLD.status!='draft' OR NEW.status NOT IN ('approved','rejected') OR NEW.version!=OLD.version+1
 OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.po_id IS DISTINCT FROM OLD.po_id
 OR NEW.vendor_id IS DISTINCT FROM OLD.vendor_id OR NEW.supplier_invoice_number IS DISTINCT FROM OLD.supplier_invoice_number
 OR NEW.qty IS DISTINCT FROM OLD.qty OR NEW.amount_cents IS DISTINCT FROM OLD.amount_cents
 OR NEW.evidence_document_id IS DISTINCT FROM OLD.evidence_document_id OR NEW.due_date IS DISTINCT FROM OLD.due_date
 OR NEW.created_by IS DISTINCT FROM OLD.created_by OR lower(NEW.reviewed_by)=lower(OLD.created_by)
 THEN rticore_raise('AP_IMMUTABLE') END;
    PERFORM CASE WHEN NEW.status='approved' AND NOT EXISTS(
 SELECT 1 FROM rticore_purchase_orders p
 WHERE p.id=NEW.po_id AND p.tenant_id=NEW.tenant_id AND p.status='approved'
 AND (SELECT coalesce(sum(r.qty),0) FROM rticore_purchase_receipts r WHERE r.po_id=p.id AND r.tenant_id=p.tenant_id)>=
 (SELECT coalesce(sum(i.qty),0) FROM rticore_ap_supplier_invoices i WHERE i.po_id=p.id AND i.tenant_id=p.tenant_id AND i.status='approved')+NEW.qty
 ) THEN rticore_raise('AP_THREE_WAY_MATCH') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_ap_review ON rticore_ap_supplier_invoices;
CREATE TRIGGER rticore_ap_review BEFORE UPDATE ON rticore_ap_supplier_invoices FOR EACH ROW EXECUTE FUNCTION rticore_ap_review_fn();

