-- rticore_compliance_parent_review: BEFORE UPDATE OF status ON rticore_sales_requirements
CREATE OR REPLACE FUNCTION rticore_compliance_parent_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='reviewed' AND NEW.compliance_status='compliant' AND EXISTS(SELECT 1 FROM rticore_tender_compliance_items c WHERE c.requirement_id=NEW.id)
 AND EXISTS(SELECT 1 FROM rticore_tender_compliance_items c WHERE c.requirement_id=NEW.id AND c.mandatory=1 AND (c.status!='reviewed' OR c.compliance_status!='compliant'))) THEN
    PERFORM rticore_raise('COMPLIANCE_CONFLICT: mandatory clauses not compliant');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_compliance_parent_review ON rticore_sales_requirements;
