-- rticore_contract_frozen: BEFORE UPDATE ON rticore_service_contracts
CREATE OR REPLACE FUNCTION rticore_contract_frozen_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.version!=OLD.version+1 OR NEW.id!=OLD.id OR NEW.tenant_id!=OLD.tenant_id OR NEW.project_id!=OLD.project_id OR NEW.customer_id!=OLD.customer_id
 OR (OLD.status!='draft' AND (NEW.model!=OLD.model OR NEW.start_date IS DISTINCT FROM OLD.start_date OR NEW.end_date IS DISTINCT FROM OLD.end_date OR NEW.notice_days!=OLD.notice_days OR NEW.recurring_cents!=OLD.recurring_cents OR NEW.renewal_cents IS DISTINCT FROM OLD.renewal_cents OR NEW.configured_by IS DISTINCT FROM OLD.configured_by OR NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.probability_pct!=OLD.probability_pct OR NEW.status NOT IN ('active','expired','churned')))) THEN
    PERFORM rticore_raise('DELIVERY_CONFLICT: approved contract snapshot is immutable');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_contract_frozen ON rticore_service_contracts;
CREATE TRIGGER rticore_contract_frozen BEFORE UPDATE ON rticore_service_contracts FOR EACH ROW EXECUTE FUNCTION rticore_contract_frozen_fn();

