-- rticore_customer_relation_cycle: BEFORE INSERT ON rticore_customer_relations
CREATE OR REPLACE FUNCTION rticore_customer_relation_cycle_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN EXISTS(WITH RECURSIVE ancestors(id) AS (SELECT NEW.parent_id UNION SELECT r.parent_id FROM rticore_customer_relations r JOIN ancestors a ON r.child_id=a.id WHERE r.tenant_id=NEW.tenant_id) SELECT 1 FROM ancestors WHERE id=NEW.child_id) THEN rticore_raise('DELIVERY_CONFLICT: customer hierarchy cycle') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_customer_relation_cycle ON rticore_customer_relations;
CREATE TRIGGER rticore_customer_relation_cycle BEFORE INSERT ON rticore_customer_relations FOR EACH ROW EXECUTE FUNCTION rticore_customer_relation_cycle_fn();

