-- rticore_cyber_assignment_flow: BEFORE UPDATE ON rticore_cyber_case_assignments
CREATE OR REPLACE FUNCTION rticore_cyber_assignment_flow_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.case_id IS DISTINCT FROM OLD.case_id
  OR NEW.assigned_at IS DISTINCT FROM OLD.assigned_at OR NEW.version!=OLD.version+1 OR NOT (
  (OLD.status IN ('assigned','returned') AND NEW.status='assigned') OR
  (OLD.status IN ('assigned','returned') AND NEW.status='submitted' AND NEW.assignee_email IS NOT DISTINCT FROM OLD.assignee_email) OR
  (OLD.status='submitted' AND NEW.status='returned' AND NEW.assignee_email IS NOT DISTINCT FROM OLD.assignee_email
   AND lower(NEW.assigned_by)!=lower(OLD.assignee_email))
 ) THEN rticore_raise('CYBER_ASSIGNMENT_IMMUTABLE') END;
    PERFORM CASE WHEN NOT EXISTS(SELECT 1 FROM rticore_cyber_cases c WHERE c.tenant_id=NEW.tenant_id AND c.id=NEW.case_id AND c.status='open')
 THEN rticore_raise('CYBER_ASSIGNMENT_CASE_NOT_OPEN') END;
    PERFORM CASE WHEN NEW.status='assigned' AND NOT EXISTS(SELECT 1 FROM rticore_members m WHERE m.email=NEW.assignee_email AND m.active=1 AND m.role IN ('defense_leader','defense_member'))
 THEN rticore_raise('CYBER_ASSIGNEE_NOT_DEFENSE_MEMBER') END;
    PERFORM CASE WHEN NEW.status IN ('assigned','returned') AND NOT EXISTS(SELECT 1 FROM rticore_members m WHERE m.email=NEW.assigned_by AND m.active=1 AND m.role IN ('defense_leader','admin'))
 THEN rticore_raise('CYBER_ASSIGNER_NOT_LEADER') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_cyber_assignment_flow ON rticore_cyber_case_assignments;
CREATE TRIGGER rticore_cyber_assignment_flow BEFORE UPDATE ON rticore_cyber_case_assignments FOR EACH ROW EXECUTE FUNCTION rticore_cyber_assignment_flow_fn();

