-- rticore_cyber_assignment_open: BEFORE INSERT ON rticore_cyber_case_assignments
CREATE OR REPLACE FUNCTION rticore_cyber_assignment_open_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN NEW.status!='assigned' OR NEW.version!=1 OR NOT EXISTS(SELECT 1 FROM rticore_cyber_cases c
  WHERE c.tenant_id=NEW.tenant_id AND c.id=NEW.case_id AND c.status='open' AND c.kind IN ('soc_incident','dfir_incident'))
 THEN rticore_raise('CYBER_ASSIGNMENT_CASE_NOT_OPEN') END;
    PERFORM CASE WHEN NOT EXISTS(SELECT 1 FROM rticore_members m WHERE m.email=NEW.assignee_email AND m.active=1 AND m.role IN ('defense_leader','defense_member'))
 THEN rticore_raise('CYBER_ASSIGNEE_NOT_DEFENSE_MEMBER') END;
    PERFORM CASE WHEN NOT EXISTS(SELECT 1 FROM rticore_members m WHERE m.email=NEW.assigned_by AND m.active=1 AND m.role IN ('defense_leader','admin'))
 THEN rticore_raise('CYBER_ASSIGNER_NOT_LEADER') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_cyber_assignment_open ON rticore_cyber_case_assignments;
CREATE TRIGGER rticore_cyber_assignment_open BEFORE INSERT ON rticore_cyber_case_assignments FOR EACH ROW EXECUTE FUNCTION rticore_cyber_assignment_open_fn();

-- rticore_cyber_case_assignment_gate: BEFORE UPDATE ON rticore_cyber_cases
CREATE OR REPLACE FUNCTION rticore_cyber_case_assignment_gate_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.status='open' AND NEW.status IN ('reviewed','rejected') AND EXISTS(SELECT 1 FROM rticore_cyber_case_assignments x WHERE x.tenant_id=OLD.tenant_id AND x.case_id=OLD.id)) THEN
    PERFORM CASE WHEN EXISTS(SELECT 1 FROM rticore_cyber_case_assignments x WHERE x.tenant_id=OLD.tenant_id AND x.case_id=OLD.id AND x.status!='submitted')
 THEN rticore_raise('CYBER_ASSIGNMENT_NOT_SUBMITTED') END;
    PERFORM CASE WHEN EXISTS(SELECT 1 FROM rticore_cyber_case_assignments x WHERE x.tenant_id=OLD.tenant_id AND x.case_id=OLD.id AND lower(x.assignee_email)=lower(NEW.reviewer_email))
 THEN rticore_raise('CYBER_REVIEWER_IS_ASSIGNEE') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_cyber_case_assignment_gate ON rticore_cyber_cases;
CREATE TRIGGER rticore_cyber_case_assignment_gate BEFORE UPDATE ON rticore_cyber_cases FOR EACH ROW EXECUTE FUNCTION rticore_cyber_case_assignment_gate_fn();

