-- rticore_cyber_case_review: BEFORE UPDATE ON rticore_cyber_cases
CREATE OR REPLACE FUNCTION rticore_cyber_case_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.project_id IS DISTINCT FROM OLD.project_id
 OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.external_ref IS DISTINCT FROM OLD.external_ref OR NEW.title IS DISTINCT FROM OLD.title
 OR NEW.severity IS DISTINCT FROM OLD.severity OR NEW.classification IS DISTINCT FROM OLD.classification
 OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at IS DISTINCT FROM OLD.created_at
 OR NEW.version!=OLD.version+1 OR NOT (
 (OLD.status='open' AND NEW.status IN ('reviewed','rejected')) OR
 (OLD.status='reviewed' AND NEW.status='closed')
 ) THEN rticore_raise('CYBER_CASE_IMMUTABLE') END;
    PERFORM CASE WHEN NEW.status IN ('reviewed','closed') AND (
 NEW.evidence_document_id IS NULL OR NEW.reviewer_email IS NULL
 OR lower(NEW.reviewer_email)=lower(NEW.created_by) OR coalesce(length(NEW.review_notes),0)<12
 ) THEN rticore_raise('CYBER_EVIDENCE_REVIEW_REQUIRED') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_cyber_case_review ON rticore_cyber_cases;
CREATE TRIGGER rticore_cyber_case_review BEFORE UPDATE ON rticore_cyber_cases FOR EACH ROW EXECUTE FUNCTION rticore_cyber_case_review_fn();

-- rticore_cyber_case_scope: BEFORE INSERT ON rticore_cyber_cases
CREATE OR REPLACE FUNCTION rticore_cyber_case_scope_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM rticore_delivery_projects p WHERE p.tenant_id=NEW.tenant_id
 AND p.id=NEW.project_id AND p.status='active'
 AND ((NEW.kind='vapt_finding' AND p.service_family='VAPT')
 OR (NEW.kind='soc_incident' AND p.service_family='SOC/MDR')
 OR (NEW.kind='dfir_incident' AND p.service_family IN ('DFIR','Incident Response','Managed Security'))))) THEN
    PERFORM rticore_raise('CYBER_PROJECT_NOT_AUTHORIZED');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_cyber_case_scope ON rticore_cyber_cases;
CREATE TRIGGER rticore_cyber_case_scope BEFORE INSERT ON rticore_cyber_cases FOR EACH ROW EXECUTE FUNCTION rticore_cyber_case_scope_fn();

-- rticore_delivery_assign_planned_pm: AFTER INSERT ON rticore_delivery_projects
CREATE OR REPLACE FUNCTION rticore_delivery_assign_planned_pm_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (EXISTS(SELECT 1 FROM rticore_delivery_planned_pm x WHERE x.tenant_id=NEW.tenant_id AND x.opportunity_id=NEW.opportunity_id)) THEN
    IF current_setting('rticore.trg_rticore_delivery_assign_planned_pm', true) = '1' THEN RETURN NULL; END IF;
    PERFORM set_config('rticore.trg_rticore_delivery_assign_planned_pm', '1', true);
    UPDATE rticore_delivery_projects SET pm_email=(SELECT x.pm_email FROM rticore_delivery_planned_pm x WHERE x.tenant_id=NEW.tenant_id AND x.opportunity_id=NEW.opportunity_id),
 start_date=(SELECT x.start_date FROM rticore_delivery_planned_pm x WHERE x.tenant_id=NEW.tenant_id AND x.opportunity_id=NEW.opportunity_id),
 end_date=(SELECT x.end_date FROM rticore_delivery_planned_pm x WHERE x.tenant_id=NEW.tenant_id AND x.opportunity_id=NEW.opportunity_id),version=version+1 WHERE id=NEW.id AND tenant_id=NEW.tenant_id;
    PERFORM set_config('rticore.trg_rticore_delivery_assign_planned_pm', '', true);
  END IF;
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_delivery_assign_planned_pm ON rticore_delivery_projects;
CREATE TRIGGER rticore_delivery_assign_planned_pm AFTER INSERT ON rticore_delivery_projects FOR EACH ROW EXECUTE FUNCTION rticore_delivery_assign_planned_pm_fn();

-- rticore_delivery_initial: AFTER INSERT ON rticore_delivery_projects
CREATE OR REPLACE FUNCTION rticore_delivery_initial_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    INSERT INTO rticore_delivery_tasks(id,tenant_id,project_id,code,title)
 SELECT NEW.id||'-'||value,NEW.tenant_id,NEW.id,value,
 CASE value WHEN 'kickoff_scope' THEN 'Konfirmasi scope baseline' WHEN 'kickoff_access' THEN 'Akses, NDA dan jadwal kickoff' WHEN 'kickoff_team' THEN 'Tim delivery dan PIC pelanggan'
 WHEN 'vapt_scope' THEN 'Testing scope, aset dan rules of engagement' WHEN 'vapt_test' THEN 'Pelaksanaan testing' WHEN 'vapt_report' THEN 'Laporan VAPT' WHEN 'vapt_retest' THEN 'Retest dan closure findings'
 WHEN 'soc_logs' THEN 'Onboarding log source dan use case' WHEN 'soc_sla' THEN 'SLA, eskalasi dan service window' WHEN 'soc_report' THEN 'Monthly service report'
 WHEN 'grc_assessment' THEN 'Assessment dan evidence' WHEN 'grc_gap' THEN 'Gap analysis' WHEN 'grc_remediation' THEN 'Remediation dan action plan'
 WHEN 'tech_license' THEN 'SKU, lisensi dan entitlement' WHEN 'tech_implementation' THEN 'Implementasi dan acceptance test' WHEN 'tech_support' THEN 'Support, warranty dan eskalasi'
 ELSE 'Deliverable dan acceptance layanan' END
 FROM rticore_json_each(CASE WHEN NEW.service_family='VAPT' THEN '["kickoff_scope","kickoff_access","kickoff_team","vapt_scope","vapt_test","vapt_report","vapt_retest"]'
 WHEN NEW.service_family IN ('SOC/MDR','Managed Security') THEN '["kickoff_scope","kickoff_access","kickoff_team","soc_logs","soc_sla","soc_report"]'
 WHEN NEW.service_family IN ('GRC','Cybersecurity Governance') THEN '["kickoff_scope","kickoff_access","kickoff_team","grc_assessment","grc_gap","grc_remediation"]'
 WHEN NEW.service_family IN ('FortiSIEM','Cybersecurity Technology') THEN '["kickoff_scope","kickoff_access","kickoff_team","tech_license","tech_implementation","tech_support"]'
 ELSE '["kickoff_scope","kickoff_access","kickoff_team","service_deliverable"]' END);
    INSERT INTO rticore_delivery_milestones(id,tenant_id,project_id,title,trigger_text,amount_cents,created_by)
 SELECT NEW.id||'-ms-'||key,NEW.tenant_id,NEW.id,coalesce(json_extract(value,'$.label'),'Termin '||(key+1)),coalesce(json_extract(value,'$.trigger'),''),
 CASE WHEN rticore_json_type(value,'$.amount') IN ('integer','real') AND (json_extract(value,'$.amount'))::numeric>0 THEN CAST(round((json_extract(value,'$.amount'))::numeric*100) AS INTEGER) ELSE NULL END,NEW.created_by
 FROM rticore_json_each(CASE WHEN json_valid(json_extract(NEW.baseline_json,'$.scope.fields.payment_milestones')) AND rticore_json_type(json_extract(NEW.baseline_json,'$.scope.fields.payment_milestones'))='array' THEN json_extract(NEW.baseline_json,'$.scope.fields.payment_milestones') ELSE '[]' END) WHERE key<20;
    INSERT INTO rticore_service_contracts(id,tenant_id,project_id,customer_id,model)
 VALUES('contract-'||NEW.opportunity_id,NEW.tenant_id,NEW.id,NEW.customer_id,CASE WHEN json_extract(NEW.baseline_json,'$.scope.fields.contract_model')='Recurring' THEN 'MRC' ELSE 'OTC' END);
    INSERT INTO rticore_operations_events(id,tenant_id,area,entity_id,action,actor_email,snapshot_json)
 VALUES(lower(hex(randomblob(16))),NEW.tenant_id,'delivery',NEW.id,'AUTO_HANDOVER',NEW.created_by,jsonb_build_object('release_id',NEW.release_id,'customer_id',NEW.customer_id,'po_number',NEW.po_number));
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_delivery_initial ON rticore_delivery_projects;
CREATE TRIGGER rticore_delivery_initial AFTER INSERT ON rticore_delivery_projects FOR EACH ROW EXECUTE FUNCTION rticore_delivery_initial_fn();

