-- rticore_delivery_soc_months: AFTER UPDATE OF start_date,end_date ON rticore_delivery_projects
CREATE OR REPLACE FUNCTION rticore_delivery_soc_months_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.service_family='SOC/MDR' AND NEW.start_date IS NOT NULL AND NEW.end_date IS NOT NULL) THEN
    INSERT INTO rticore_delivery_tasks(id,tenant_id,project_id,code,title,period)
 SELECT NEW.id||'-soc-'||month,NEW.tenant_id,NEW.id,'soc_report','Monthly service report',month FROM (
 WITH RECURSIVE months(month,n) AS (SELECT substr(NEW.start_date,1,7),1 UNION ALL SELECT strftime('%Y-%m',month||'-01','+1 month'),n+1 FROM months WHERE month<substr(NEW.end_date,1,7) AND n<60)
 SELECT month FROM months) ON CONFLICT DO NOTHING;
  END IF;
  RETURN NULL;
END
$fn$;
