-- rticore_document_won_gate: BEFORE UPDATE OF stage ON rticore_sales_opportunities
CREATE OR REPLACE FUNCTION rticore_document_won_gate_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.stage='closed_won' AND OLD.stage!='closed_won') THEN
    PERFORM CASE WHEN NOT EXISTS(
 SELECT 1 FROM rticore_sales_releases r
 JOIN rticore_document_evidence p ON p.reference=r.proposal_reference AND p.sha256=r.proposal_sha256 AND p.kind='proposal' AND p.release_id=r.id
 JOIN rticore_sales_submissions s ON s.release_id=r.id AND s.status='verified'
 JOIN rticore_document_evidence m ON m.reference=s.evidence_reference AND m.sha256=s.evidence_sha256 AND m.kind='submission' AND m.release_id=r.id
 JOIN rticore_sales_negotiations n ON n.release_id=r.id AND n.decision='approved' AND n.rowid=(SELECT max(n2.rowid) FROM rticore_sales_negotiations n2 WHERE n2.release_id=r.id)
 JOIN rticore_document_evidence e ON e.reference=n.evidence_reference AND e.sha256=n.evidence_sha256 AND e.kind='negotiation' AND e.release_id=r.id
 JOIN rticore_sales_po_checks c ON c.release_id=r.id AND c.opportunity_id=NEW.id
 JOIN rticore_sales_award_documents a ON a.id=c.award_id AND a.release_id=r.id
 JOIN rticore_document_evidence o ON o.reference=a.archive_reference AND o.sha256=a.original_sha256 AND o.kind=a.document_kind AND o.release_id=r.id
 WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id AND r.status='approved'
 AND p.tenant_id=r.tenant_id AND m.tenant_id=r.tenant_id AND e.tenant_id=r.tenant_id AND o.tenant_id=r.tenant_id
 AND p.opportunity_id=NEW.id AND m.opportunity_id=NEW.id AND e.opportunity_id=NEW.id AND o.opportunity_id=NEW.id)
 THEN rticore_raise('FLOW_CONFLICT: Won requires all four stored originals of current release') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_document_won_gate ON rticore_sales_opportunities;
CREATE TRIGGER rticore_document_won_gate BEFORE UPDATE OF stage ON rticore_sales_opportunities FOR EACH ROW EXECUTE FUNCTION rticore_document_won_gate_fn();

