-- rticore_erp_access_change_apply: AFTER UPDATE OF status ON rticore_erp_access_change_requests
CREATE OR REPLACE FUNCTION rticore_erp_access_change_apply_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='approved' AND OLD.status='pending') THEN
    UPDATE rticore_erp_capability_grants
 SET status='revoked',version=version+1,reviewed_by=NEW.reviewed_by,
 review_notes=NEW.review_notes,reviewed_at=rticore_now_text()
 WHERE id=NEW.grant_id AND tenant_id=NEW.tenant_id AND status='approved';
    GET DIAGNOSTICS _rc = ROW_COUNT;
    PERFORM CASE WHEN _rc!=1 THEN rticore_raise('ERP_REVOKE_CONFLICT') END;
  END IF;
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_erp_access_change_apply ON rticore_erp_access_change_requests;
CREATE TRIGGER rticore_erp_access_change_apply AFTER UPDATE OF status ON rticore_erp_access_change_requests FOR EACH ROW EXECUTE FUNCTION rticore_erp_access_change_apply_fn();

