CREATE OR REPLACE FUNCTION rticore_erp_access_change_no_rewrite_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM rticore_erp_org_units u JOIN rticore_members m
 ON lower(m.email)=lower(NEW.email) AND m.active=1 WHERE u.tenant_id=NEW.tenant_id AND u.id=NEW.unit_id AND u.active=1)) THEN
    PERFORM rticore_raise('ACCESS_CHANGE_UNKNOWN_USER_OR_UNIT');
  END IF;
  RETURN NEW;
END
$fn$;
