-- rticore_erp_access_change_review: BEFORE UPDATE ON rticore_erp_access_changes
CREATE OR REPLACE FUNCTION rticore_erp_access_change_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.status!='pending' OR NEW.status NOT IN ('approved','rejected') OR
 NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.email IS DISTINCT FROM OLD.email OR
 NEW.capability IS DISTINCT FROM OLD.capability OR NEW.unit_id IS DISTINCT FROM OLD.unit_id OR NEW.operation IS DISTINCT FROM OLD.operation OR
 NEW.requested_by IS DISTINCT FROM OLD.requested_by OR NEW.reason IS DISTINCT FROM OLD.reason OR
 NEW.reviewed_by IS NULL OR lower(NEW.reviewed_by)=lower(OLD.requested_by) OR lower(NEW.reviewed_by)=lower(OLD.email)) THEN
    PERFORM rticore_raise('ACCESS_CHANGE_IMMUTABLE');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_erp_access_change_review ON rticore_erp_access_changes;
CREATE TRIGGER rticore_erp_access_change_review BEFORE UPDATE ON rticore_erp_access_changes FOR EACH ROW EXECUTE FUNCTION rticore_erp_access_change_review_fn();

