 AND NOT EXISTS(SELECT 1 FROM rticore_gl_journals j WHERE j.tenant_id=p.tenant_id AND j.period_id=p.id AND j.status IN ('draft','approved')))) THEN
    PERFORM rticore_raise('GL_CLOSE_UNPOSTED_JOURNALS');
