-- rticore_erp_grant_change_review: BEFORE UPDATE ON rticore_erp_access_change_requests
CREATE OR REPLACE FUNCTION rticore_erp_grant_change_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.status!='pending' OR NEW.status NOT IN ('approved','rejected') OR NEW.version!=OLD.version+1
 OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.grant_id IS DISTINCT FROM OLD.grant_id
 OR NEW.action IS DISTINCT FROM OLD.action OR NEW.reason IS DISTINCT FROM OLD.reason OR NEW.requested_by IS DISTINCT FROM OLD.requested_by
 OR lower(NEW.reviewed_by)=lower(OLD.requested_by)) THEN
    PERFORM rticore_raise('ERP_ACCESS_CHANGE_IMMUTABLE');
  END IF;
  RETURN NEW;
END
$fn$;
