-- rticore_erp_grants_review: BEFORE UPDATE ON rticore_erp_capability_grants
CREATE OR REPLACE FUNCTION rticore_erp_grants_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN NEW.version!=OLD.version+1 OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
 OR NEW.email IS DISTINCT FROM OLD.email OR NEW.capability IS DISTINCT FROM OLD.capability OR NEW.unit_id IS DISTINCT FROM OLD.unit_id
 OR NEW.requested_by IS DISTINCT FROM OLD.requested_by OR NEW.created_at IS DISTINCT FROM OLD.created_at
 OR NOT (
 (OLD.status='pending' AND NEW.status IN ('approved','rejected') AND lower(NEW.reviewed_by)!=lower(OLD.requested_by) AND lower(NEW.reviewed_by)!=lower(OLD.email))
 OR (OLD.status='approved' AND NEW.status='revoked' AND EXISTS(
 SELECT 1 FROM rticore_erp_access_change_requests c WHERE c.grant_id=OLD.id AND c.tenant_id=OLD.tenant_id
 AND c.status='approved' AND lower(c.reviewed_by)=lower(NEW.reviewed_by)
 AND lower(c.reviewed_by)!=lower(OLD.email)))
 ) THEN rticore_raise('ERP_GRANT_IMMUTABLE') END;
  RETURN NEW;
END
$fn$;
