-- rticore_erp_org_parent: BEFORE INSERT ON rticore_erp_org_units
CREATE OR REPLACE FUNCTION rticore_erp_org_parent_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN NEW.kind='legal_entity' AND NEW.parent_id IS NOT NULL THEN rticore_raise('ERP_ORG_PARENT') END;
    PERFORM CASE WHEN NEW.kind!='legal_entity' AND NOT EXISTS(
  SELECT 1 FROM rticore_erp_org_units p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.parent_id AND p.active=1
  AND ( (NEW.kind='division' AND p.kind='legal_entity')
     OR (NEW.kind='department' AND p.kind='division')
     OR (NEW.kind='team' AND p.kind='department')
     OR (NEW.kind='cost_center' AND p.kind IN ('division','department')) )
 ) THEN rticore_raise('ERP_ORG_PARENT') END;
  RETURN NEW;
END
$fn$;
