-- rticore_erp_payment_no_update: BEFORE UPDATE ON rticore_erp_treasury_payment_requests
CREATE OR REPLACE FUNCTION rticore_erp_payment_no_update_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.status NOT IN ('pending','approved','sent') OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
 OR NEW.ap_invoice_id IS DISTINCT FROM OLD.ap_invoice_id OR NEW.amount_cents IS DISTINCT FROM OLD.amount_cents
 OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.beneficiary_reference IS DISTINCT FROM OLD.beneficiary_reference
 OR NEW.bank_account_token IS DISTINCT FROM OLD.bank_account_token OR NEW.bank_idempotency_key IS DISTINCT FROM OLD.bank_idempotency_key
 OR NEW.requested_by IS DISTINCT FROM OLD.requested_by
 OR NOT ((OLD.status='pending' AND NEW.status IN ('approved','rejected') AND NEW.approved_by IS NOT NULL AND lower(NEW.approved_by)!=lower(OLD.requested_by))
 OR (OLD.status='approved' AND NEW.status='sent' AND NEW.approved_by IS NOT DISTINCT FROM OLD.approved_by)
 OR (OLD.status='sent' AND NEW.status IN ('settled','failed') AND NEW.approved_by IS NOT DISTINCT FROM OLD.approved_by))) THEN
    PERFORM rticore_raise('PAYMENT_TRANSITION_INVALID');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_erp_payment_no_update ON rticore_erp_treasury_payment_requests;
