-- rticore_erp_policy_change_apply: AFTER UPDATE OF status ON rticore_erp_role_policy_changes
CREATE OR REPLACE FUNCTION rticore_erp_policy_change_apply_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='approved' AND OLD.status='pending') THEN
    PERFORM CASE WHEN coalesce((SELECT allowed FROM rticore_erp_role_capability_matrix
 WHERE role=NEW.role AND capability=NEW.capability),0)!=NEW.from_allowed
 THEN rticore_raise('ROLE_POLICY_STALE') END;
    INSERT INTO rticore_erp_role_capability_matrix(role,capability,allowed) VALUES(NEW.role,NEW.capability,NEW.to_allowed)
 ON CONFLICT(role,capability) DO UPDATE SET allowed=excluded.allowed,updated_at=rticore_now_text();
  END IF;
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_erp_policy_change_apply ON rticore_erp_role_policy_changes;
CREATE TRIGGER rticore_erp_policy_change_apply AFTER UPDATE OF status ON rticore_erp_role_policy_changes FOR EACH ROW EXECUTE FUNCTION rticore_erp_policy_change_apply_fn();

