-- rticore_feasibility_alloc_cancel: AFTER UPDATE OF status ON rticore_resource_allocations
CREATE OR REPLACE FUNCTION rticore_feasibility_alloc_cancel_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.status!=NEW.status) THEN
    INSERT INTO rticore_feasibility_history(id,tenant_id,opportunity_id,entity_type,entity_id,snapshot_json,action,actor)
 VALUES(lower(hex(randomblob(16))),NEW.tenant_id,NEW.opportunity_id,'allocation',NEW.id,jsonb_build_object('old_status',OLD.status,'new_status',NEW.status),'STATUS_CHANGE',NEW.created_by);
    UPDATE rticore_feasibility_plans SET status='draft',reviewed_by=NULL,review_notes=NULL,reviewed_at=NULL,version=version+1
 WHERE tenant_id=NEW.tenant_id AND opportunity_id=NEW.opportunity_id AND status='approved';
  END IF;
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_feasibility_alloc_cancel ON rticore_resource_allocations;
