DECLARE _rc bigint := 0;
BEGIN
    INSERT INTO rticore_feasibility_history(id,tenant_id,opportunity_id,entity_type,entity_id,snapshot_json,action,actor)
 VALUES(lower(hex(randomblob(16))),NEW.tenant_id,NEW.opportunity_id,'allocation',NEW.id,
 jsonb_build_object('person_id',NEW.person_id,'month',NEW.allocation_month,'days',NEW.person_days,'unit_cost',NEW.daily_cost_snapshot),
 'CREATE',NEW.created_by);
    UPDATE rticore_feasibility_plans SET status='draft',reviewed_by=NULL,review_notes=NULL,reviewed_at=NULL,version=version+1
 WHERE tenant_id=NEW.tenant_id AND opportunity_id=NEW.opportunity_id;
  RETURN NULL;
END
$fn$;
