-- rticore_feasibility_alloc_insert: BEFORE INSERT ON rticore_resource_allocations
CREATE OR REPLACE FUNCTION rticore_feasibility_alloc_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN NOT EXISTS(
  SELECT 1 FROM rticore_resource_people p WHERE p.id=NEW.person_id AND p.tenant_id=NEW.tenant_id AND p.active=1
  AND NEW.person_days+coalesce((SELECT sum(a.person_days) FROM rticore_resource_allocations a WHERE a.tenant_id=NEW.tenant_id AND a.person_id=NEW.person_id AND a.allocation_month=NEW.allocation_month AND a.status='active'),0)
  <=p.capacity_pd_month
 ) THEN rticore_raise('RESOURCE_CAPACITY_CONFLICT') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_feasibility_alloc_insert ON rticore_resource_allocations;
CREATE TRIGGER rticore_feasibility_alloc_insert BEFORE INSERT ON rticore_resource_allocations FOR EACH ROW EXECUTE FUNCTION rticore_feasibility_alloc_insert_fn();

-- rticore_feasibility_alloc_update: BEFORE UPDATE OF person_days,allocation_month,person_id,status ON rticore_resource_allocations
CREATE OR REPLACE FUNCTION rticore_feasibility_alloc_update_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='active') THEN
    PERFORM CASE WHEN NOT EXISTS(
  SELECT 1 FROM rticore_resource_people p WHERE p.id=NEW.person_id AND p.tenant_id=NEW.tenant_id AND p.active=1
  AND NEW.person_days+coalesce((SELECT sum(a.person_days) FROM rticore_resource_allocations a WHERE a.tenant_id=NEW.tenant_id AND a.person_id=NEW.person_id AND a.allocation_month=NEW.allocation_month AND a.status='active' AND a.id!=OLD.id),0)
  <=p.capacity_pd_month
 ) THEN rticore_raise('RESOURCE_CAPACITY_CONFLICT') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_feasibility_alloc_update ON rticore_resource_allocations;
CREATE TRIGGER rticore_feasibility_alloc_update BEFORE UPDATE OF person_days,allocation_month,person_id,status ON rticore_resource_allocations FOR EACH ROW EXECUTE FUNCTION rticore_feasibility_alloc_update_fn();

