    UPDATE rticore_feasibility_plans SET status='draft',reviewed_by=NULL,review_notes=NULL,reviewed_at=NULL,version=version+1,updated_at=rticore_now_text()
 WHERE tenant_id=NEW.tenant_id AND opportunity_id=NEW.id AND status='approved';
  END IF;
