-- rticore_feasibility_stage_gate: BEFORE UPDATE OF stage ON rticore_sales_opportunities
CREATE OR REPLACE FUNCTION rticore_feasibility_stage_gate_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.stage!=OLD.stage AND NEW.stage IN ('commercial_review','quotation_sent','negotiation','pending_po','closed_won')
 AND EXISTS(SELECT 1 FROM rticore_feasibility_plans p WHERE p.tenant_id=NEW.tenant_id AND p.opportunity_id=NEW.id)) THEN
    PERFORM CASE WHEN EXISTS(SELECT 1 FROM rticore_solution_feasibility_gaps f WHERE f.tenant_id=NEW.tenant_id AND f.opportunity_id=NEW.id AND f.is_gap=1)
 THEN rticore_raise('FEASIBILITY_CONFLICT: resources, supplier quotation or cost review invalid') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_feasibility_stage_gate ON rticore_sales_opportunities;
CREATE TRIGGER rticore_feasibility_stage_gate BEFORE UPDATE OF stage ON rticore_sales_opportunities FOR EACH ROW EXECUTE FUNCTION rticore_feasibility_stage_gate_fn();

-- rticore_flexguard_event_guards: BEFORE INSERT ON rticore_flexguard_events
CREATE OR REPLACE FUNCTION rticore_flexguard_event_guards_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN NOT EXISTS(
   SELECT 1 FROM rticore_flexguard_wallets w JOIN rticore_service_contracts c ON c.id=w.contract_id AND c.tenant_id=w.tenant_id
   WHERE w.id=NEW.wallet_id AND w.tenant_id=NEW.tenant_id AND w.status='active'
   AND c.status='active' AND c.model='FlexGuard' AND c.end_date>=rticore_date_text('now')
 ) AND NEW.kind!='EXPIRY' THEN rticore_raise('FLEXGUARD_WALLET_NOT_ACTIVE') END;
    PERFORM CASE WHEN NEW.kind='EXPIRY' AND NOT EXISTS(
   SELECT 1 FROM rticore_flexguard_wallets w JOIN rticore_service_contracts c ON c.id=w.contract_id
   WHERE w.id=NEW.wallet_id AND c.end_date<rticore_date_text('now')
 ) THEN rticore_raise('FLEXGUARD_NOT_EXPIRED') END;
    PERFORM CASE WHEN NEW.kind IN ('ISSUE','TOPUP') AND NOT EXISTS(
   SELECT 1 FROM rticore_flexguard_wallets w
   JOIN rticore_service_contracts c ON c.id=w.contract_id AND c.tenant_id=w.tenant_id
   JOIN rticore_delivery_projects p ON p.id=c.project_id AND p.tenant_id=c.tenant_id
   JOIN rticore_billing_invoices i ON i.project_id=p.id AND i.tenant_id=p.tenant_id
   WHERE w.id=NEW.wallet_id AND w.tenant_id=NEW.tenant_id AND i.id=NEW.invoice_id
   AND i.status='approved' AND
   (SELECT coalesce(sum(pay.amount_cents),0) FROM rticore_billing_payments pay
     WHERE pay.tenant_id=i.tenant_id AND pay.invoice_id=i.id AND pay.status='approved')>=i.amount_cents+i.vat_cents
 ) THEN rticore_raise('FLEXGUARD_PAYMENT_UNVERIFIED') END;
    PERFORM CASE WHEN NEW.kind IN ('ISSUE','TOPUP') AND
  (SELECT coalesce(sum(e.units),0) FROM rticore_flexguard_events e
    WHERE e.wallet_id=NEW.wallet_id AND e.kind IN ('ISSUE','TOPUP'))+NEW.units >
  (SELECT entitlement_units FROM rticore_flexguard_wallets WHERE id=NEW.wallet_id)
 THEN rticore_raise('FLEXGUARD_QUOTA_EXCEEDED') END;
    PERFORM CASE WHEN NEW.kind NOT IN ('ISSUE','TOPUP') AND NEW.invoice_id IS NOT NULL
  THEN rticore_raise('FLEXGUARD_INVOICE_INVALID') END;
    PERFORM CASE WHEN NEW.kind IN ('RESERVE','RELEASE','DEBIT') AND NOT EXISTS(
  SELECT 1 FROM rticore_flexguard_wallets w JOIN rticore_service_contracts c ON c.id=w.contract_id
  JOIN rticore_delivery_projects p ON p.id=c.project_id
  JOIN rticore_sales_opportunities d ON d.company_id=p.customer_id AND d.tenant_id=p.tenant_id
  WHERE w.id=NEW.wallet_id AND d.id=NEW.opportunity_id AND d.stage='closed_won'
 ) THEN rticore_raise('FLEXGUARD_OPPORTUNITY_INVALID') END;
    PERFORM CASE WHEN NEW.kind IN ('RESERVE','EXPIRY') AND
  NEW.units>(SELECT coalesce(sum(CASE e.kind
    WHEN 'ISSUE' THEN e.units WHEN 'TOPUP' THEN e.units
    WHEN 'RELEASE' THEN e.units WHEN 'REFUND' THEN e.units
    WHEN 'RESERVE' THEN -e.units WHEN 'EXPIRY' THEN -e.units ELSE 0 END),0)
    FROM rticore_flexguard_events e WHERE e.wallet_id=NEW.wallet_id)
  THEN rticore_raise('FLEXGUARD_INSUFFICIENT_AVAILABLE') END;
    PERFORM CASE WHEN NEW.kind IN ('RELEASE','DEBIT') AND NOT EXISTS(
  SELECT 1 FROM rticore_flexguard_events src
  WHERE src.id=NEW.source_event_id AND src.wallet_id=NEW.wallet_id AND src.kind='RESERVE'
    AND src.opportunity_id=NEW.opportunity_id
    AND src.units>=NEW.units+coalesce((SELECT sum(t.units) FROM rticore_flexguard_events t
         WHERE t.source_event_id=src.id AND t.kind IN ('RELEASE','DEBIT')),0)
 ) THEN rticore_raise('FLEXGUARD_RESERVATION_EXCEEDED') END;
    PERFORM CASE WHEN NEW.kind='REFUND' AND NOT EXISTS(
   SELECT 1 FROM rticore_flexguard_events src WHERE src.id=NEW.source_event_id
    AND src.kind='DEBIT' AND src.wallet_id=NEW.wallet_id
    AND src.units>=NEW.units+coalesce((SELECT sum(t.units) FROM rticore_flexguard_events t
        WHERE t.source_event_id=src.id AND t.kind='REFUND'),0)
 ) THEN rticore_raise('FLEXGUARD_REFUND_EXCEEDED') END;
    PERFORM CASE WHEN NEW.kind='DEBIT' AND (NEW.document_id IS NULL OR length(NEW.document_id)<8)
  THEN rticore_raise('FLEXGUARD_EVIDENCE_MISSING') END;
    PERFORM CASE WHEN NEW.kind IN ('RELEASE','DEBIT','REFUND') AND NEW.source_event_id IS NULL
  THEN rticore_raise('FLEXGUARD_SOURCE_MISSING') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flexguard_event_guards ON rticore_flexguard_events;
CREATE TRIGGER rticore_flexguard_event_guards BEFORE INSERT ON rticore_flexguard_events FOR EACH ROW EXECUTE FUNCTION rticore_flexguard_event_guards_fn();

