-- rticore_flow_account: AFTER UPDATE OF legal_name,data_json ON rticore_sales_accounts
CREATE OR REPLACE FUNCTION rticore_flow_account_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.legal_name!=NEW.legal_name OR OLD.data_json!=NEW.data_json) THEN
    UPDATE rticore_sales_releases SET status='superseded' WHERE tenant_id=NEW.tenant_id AND opportunity_id IN (SELECT id FROM rticore_sales_opportunities WHERE company_id=NEW.id AND stage NOT IN ('closed_won','closed_lost')) AND status!='superseded';
    UPDATE rticore_sales_submissions SET status='superseded' WHERE tenant_id=NEW.tenant_id AND opportunity_id IN (SELECT id FROM rticore_sales_opportunities WHERE company_id=NEW.id AND stage NOT IN ('closed_won','closed_lost')) AND status IN ('reported','verified');
    DELETE FROM rticore_sales_po_checks WHERE tenant_id=NEW.tenant_id AND opportunity_id IN (SELECT id FROM rticore_sales_opportunities WHERE company_id=NEW.id AND stage NOT IN ('closed_won','closed_lost'));
    UPDATE rticore_sales_opportunities SET stage='solution_design' WHERE company_id=NEW.id AND stage IN ('commercial_review','quotation_sent','negotiation','pending_po');
  END IF;
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flow_account ON rticore_sales_accounts;
CREATE TRIGGER rticore_flow_account AFTER UPDATE OF legal_name,data_json ON rticore_sales_accounts FOR EACH ROW EXECUTE FUNCTION rticore_flow_account_fn();

