CREATE OR REPLACE FUNCTION rticore_flow_award_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM rticore_sales_releases r WHERE r.id=NEW.release_id AND r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.opportunity_id AND r.status='approved')) THEN
    PERFORM rticore_raise('FLOW_CONFLICT: current proposal release required for award');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flow_award_insert ON rticore_sales_award_documents;
