DECLARE _rc bigint := 0;
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM rticore_sales_releases r WHERE r.id=NEW.release_id AND r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.opportunity_id AND r.status='approved')) THEN
    PERFORM rticore_raise('FLOW_CONFLICT: award belongs to superseded release');
  END IF;
  RETURN NEW;
END
