-- rticore_flow_boq: AFTER UPDATE ON rticore_boq
CREATE OR REPLACE FUNCTION rticore_flow_boq_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.status='approved' AND (NEW.status!=OLD.status OR NEW.edit_seq!=OLD.edit_seq OR NEW.line_items_json!=OLD.line_items_json OR NEW.payment_terms!=OLD.payment_terms OR NEW.vat_rate!=OLD.vat_rate)) THEN
    UPDATE rticore_sales_releases SET status='superseded' WHERE boq_id=NEW.id AND status!='superseded';
    UPDATE rticore_sales_submissions SET status='superseded' WHERE boq_id=NEW.id AND status IN ('reported','verified');
    DELETE FROM rticore_sales_po_checks WHERE boq_id=NEW.id;
    UPDATE rticore_sales_opportunities SET stage='solution_design' WHERE id=NEW.opportunity_id AND stage IN ('commercial_review','quotation_sent','negotiation','pending_po');
  END IF;
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flow_boq ON rticore_boq;
CREATE TRIGGER rticore_flow_boq AFTER UPDATE ON rticore_boq FOR EACH ROW EXECUTE FUNCTION rticore_flow_boq_fn();

-- rticore_flow_lost: AFTER UPDATE OF stage ON rticore_sales_opportunities
CREATE OR REPLACE FUNCTION rticore_flow_lost_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.stage='closed_lost' AND OLD.stage!='closed_lost') THEN
    UPDATE rticore_sales_releases SET status='superseded' WHERE tenant_id=NEW.tenant_id AND opportunity_id=NEW.id AND status!='superseded';
    UPDATE rticore_sales_submissions SET status='superseded' WHERE tenant_id=NEW.tenant_id AND opportunity_id=NEW.id AND status IN ('reported','verified');
    DELETE FROM rticore_sales_po_checks WHERE tenant_id=NEW.tenant_id AND opportunity_id=NEW.id;
  END IF;
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flow_lost ON rticore_sales_opportunities;
CREATE TRIGGER rticore_flow_lost AFTER UPDATE OF stage ON rticore_sales_opportunities FOR EACH ROW EXECUTE FUNCTION rticore_flow_lost_fn();

-- rticore_flow_material: AFTER UPDATE OF title,estimated_value_idr,data_json,company_id ON rticore_sales_opportunities
CREATE OR REPLACE FUNCTION rticore_flow_material_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
