CREATE OR REPLACE FUNCTION rticore_flow_po_edit_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (jsonb_build_array(json_extract(OLD.data_json,'$.po_number'),json_extract(OLD.data_json,'$.po_date'),json_extract(OLD.data_json,'$.po_reference'),json_extract(OLD.data_json,'$.po_amount_before_vat'),json_extract(OLD.data_json,'$.scope_reconciliation'))
 IS DISTINCT FROM jsonb_build_array(json_extract(NEW.data_json,'$.po_number'),json_extract(NEW.data_json,'$.po_date'),json_extract(NEW.data_json,'$.po_reference'),json_extract(NEW.data_json,'$.po_amount_before_vat'),json_extract(NEW.data_json,'$.scope_reconciliation'))) THEN
    DELETE FROM rticore_sales_po_checks WHERE tenant_id=NEW.tenant_id AND opportunity_id=NEW.id;
  END IF;
  RETURN NULL;
END
$fn$;
