-- rticore_flow_po_insert: BEFORE INSERT ON rticore_sales_po_checks
CREATE OR REPLACE FUNCTION rticore_flow_po_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NOT EXISTS(
 SELECT 1 FROM rticore_sales_opportunities d
 JOIN rticore_sales_releases r ON r.opportunity_id=d.id AND r.tenant_id=d.tenant_id
 JOIN rticore_boq b ON b.id=r.boq_id AND b.edit_seq=r.boq_edit_seq
 JOIN rticore_sales_award_documents a ON a.id=NEW.award_id AND a.release_id=r.id AND a.tenant_id=d.tenant_id AND a.opportunity_id=d.id
 JOIN rticore_sales_negotiations n ON n.release_id=r.id
 JOIN rticore_sales_submissions sub ON sub.id=n.submission_id AND sub.release_id=r.id AND sub.status='verified'
 WHERE d.id=NEW.opportunity_id AND d.tenant_id=NEW.tenant_id AND d.stage='pending_po' AND r.id=NEW.release_id AND r.status='approved'
 AND b.id=NEW.boq_id AND b.status='approved' AND b.id=json_extract(d.data_json,'$.boq_id')
 AND n.decision='approved' AND n.rowid=(SELECT max(n2.rowid) FROM rticore_sales_negotiations n2 WHERE n2.release_id=r.id)
 AND abs(n.amount_before_vat-NEW.po_amount_before_vat)<0.01 AND abs(NEW.quotation_amount_before_vat-NEW.po_amount_before_vat)<0.01
 AND lower(trim(d.created_by))!=lower(trim(NEW.verified_by))
 AND a.document_kind IN ('po','spk') AND lower(a.document_number)=lower(NEW.po_number)
 AND a.finance_reviewed_by IS NOT NULL AND a.legal_reviewed_by IS NOT NULL
 AND lower(trim(a.finance_reviewed_by))!=lower(trim(a.legal_reviewed_by))
 AND a.po_data_json::jsonb=jsonb_build_object('po_number',coalesce(json_extract(d.data_json,'$.po_number'),''),'po_date',coalesce(json_extract(d.data_json,'$.po_date'),''),'po_reference',coalesce(json_extract(d.data_json,'$.po_reference'),''),'po_amount_before_vat',coalesce(json_extract(d.data_json,'$.po_amount_before_vat'),''),'scope_reconciliation',coalesce(json_extract(d.data_json,'$.scope_reconciliation'),''))
 AND NEW.po_number=json_extract(d.data_json,'$.po_number') AND NEW.po_date=json_extract(d.data_json,'$.po_date') AND NEW.po_reference=json_extract(d.data_json,'$.po_reference')
)) THEN
    PERFORM rticore_raise('FLOW_CONFLICT: PO must match current release, approved negotiation and independently reviewed original');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flow_po_insert ON rticore_sales_po_checks;
CREATE TRIGGER rticore_flow_po_insert BEFORE INSERT ON rticore_sales_po_checks FOR EACH ROW EXECUTE FUNCTION rticore_flow_po_insert_fn();

