-- rticore_flow_release_update: BEFORE UPDATE ON rticore_sales_releases
CREATE OR REPLACE FUNCTION rticore_flow_release_update_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NOT (
 (OLD.status='scoped' AND NEW.status='proposed') OR
 (OLD.status='proposed' AND NEW.status='approved') OR
 (OLD.status IN ('scoped','proposed','approved') AND NEW.status='superseded'))) THEN
    PERFORM rticore_raise('FLOW_CONFLICT: release is immutable; create a revision');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flow_release_update ON rticore_sales_releases;
CREATE TRIGGER rticore_flow_release_update BEFORE UPDATE ON rticore_sales_releases FOR EACH ROW EXECUTE FUNCTION rticore_flow_release_update_fn();

-- rticore_flow_stage: BEFORE UPDATE OF stage ON rticore_sales_opportunities
CREATE OR REPLACE FUNCTION rticore_flow_stage_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.stage!=OLD.stage AND NEW.stage IN ('commercial_review','quotation_sent','negotiation','pending_po','closed_won')) THEN
    PERFORM CASE WHEN NOT EXISTS(SELECT 1 FROM rticore_sales_releases r WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id
 AND (NEW.stage='commercial_review' AND r.status IN ('proposed','approved') OR NEW.stage!='commercial_review' AND r.status='approved'))
 THEN rticore_raise('FLOW_CONFLICT: scope and proposal approval required') END;
    PERFORM CASE WHEN NOT EXISTS(SELECT 1 FROM rticore_sales_releases r JOIN rticore_boq b ON b.id=r.boq_id WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id AND r.status IN ('proposed','approved') AND b.status='approved' AND b.edit_seq=r.boq_edit_seq AND b.id=json_extract(NEW.data_json,'$.boq_id') AND b.quotation_number=json_extract(NEW.data_json,'$.quotation_number')) THEN rticore_raise('FLOW_CONFLICT: selected BoQ must match proposal release') END;
    PERFORM CASE WHEN NEW.stage IN ('negotiation','pending_po','closed_won') AND NOT EXISTS(
 SELECT 1 FROM rticore_sales_submissions s JOIN rticore_sales_releases r ON r.id=s.release_id
 WHERE s.tenant_id=NEW.tenant_id AND s.opportunity_id=NEW.id AND s.status='verified' AND r.status='approved')
 THEN rticore_raise('FLOW_CONFLICT: verified submission of current release required') END;
    PERFORM CASE WHEN NEW.stage IN ('pending_po','closed_won') AND NOT EXISTS(
 SELECT 1 FROM rticore_sales_negotiations n JOIN rticore_sales_releases r ON r.id=n.release_id
 WHERE n.tenant_id=NEW.tenant_id AND n.opportunity_id=NEW.id AND r.status='approved' AND n.decision='approved'
 AND n.rowid=(SELECT max(n2.rowid) FROM rticore_sales_negotiations n2 WHERE n2.release_id=r.id))
 THEN rticore_raise('FLOW_CONFLICT: latest customer negotiation must be approved') END;
    PERFORM CASE WHEN NEW.stage='closed_won' AND NOT EXISTS(
 SELECT 1 FROM rticore_sales_po_checks p JOIN rticore_sales_releases r ON r.id=p.release_id JOIN rticore_sales_award_documents a ON a.id=p.award_id
 WHERE p.tenant_id=NEW.tenant_id AND p.opportunity_id=NEW.id AND r.status='approved' AND a.release_id=r.id
 AND a.finance_reviewed_by IS NOT NULL AND a.legal_reviewed_by IS NOT NULL)
 THEN rticore_raise('FLOW_CONFLICT: current release PO with Finance and Legal review required') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flow_stage ON rticore_sales_opportunities;
CREATE TRIGGER rticore_flow_stage BEFORE UPDATE OF stage ON rticore_sales_opportunities FOR EACH ROW EXECUTE FUNCTION rticore_flow_stage_fn();

-- rticore_flow_submission_insert: BEFORE INSERT ON rticore_sales_submissions
CREATE OR REPLACE FUNCTION rticore_flow_submission_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM rticore_sales_releases r JOIN rticore_boq b ON b.id=r.boq_id
 WHERE r.id=NEW.release_id AND r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.opportunity_id AND r.status='approved'
 AND r.boq_id=NEW.boq_id AND r.boq_version=NEW.boq_version AND b.edit_seq=r.boq_edit_seq AND b.status='approved' AND b.quotation_number=NEW.quotation_number)) THEN
    PERFORM rticore_raise('FLOW_CONFLICT: approved proposal release required');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flow_submission_insert ON rticore_sales_submissions;
CREATE TRIGGER rticore_flow_submission_insert BEFORE INSERT ON rticore_sales_submissions FOR EACH ROW EXECUTE FUNCTION rticore_flow_submission_insert_fn();

-- rticore_flow_submission_review: BEFORE UPDATE OF status ON rticore_sales_submissions
CREATE OR REPLACE FUNCTION rticore_flow_submission_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='verified' AND (lower(trim(NEW.created_by))=lower(trim(NEW.verified_by)) OR NOT EXISTS(
 SELECT 1 FROM rticore_sales_releases r WHERE r.id=NEW.release_id AND r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.opportunity_id AND r.status='approved'))) THEN
    PERFORM rticore_raise('FLOW_CONFLICT: stale submission or maker checker violation');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flow_submission_review ON rticore_sales_submissions;
