-- rticore_flow_version: AFTER UPDATE OF title,estimated_value_idr,data_json,stage,company_id ON rticore_sales_opportunities
CREATE OR REPLACE FUNCTION rticore_flow_version_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    IF current_setting('rticore.trg_rticore_flow_version', true) = '1' THEN RETURN NULL; END IF;
    PERFORM set_config('rticore.trg_rticore_flow_version', '1', true);
    UPDATE rticore_sales_opportunities SET flow_version=OLD.flow_version+1 WHERE id=NEW.id;
    PERFORM set_config('rticore.trg_rticore_flow_version', '', true);
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_flow_version ON rticore_sales_opportunities;
