-- rticore_gl_close_apply: AFTER UPDATE OF status ON rticore_gl_close_requests
CREATE OR REPLACE FUNCTION rticore_gl_close_apply_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='approved' AND OLD.status='pending') THEN
    PERFORM CASE WHEN NEW.snapshot_debits IS NULL OR NEW.snapshot_credits IS NULL OR
 NOT EXISTS(SELECT 1 FROM rticore_gl_periods p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.period_id AND p.status='open') OR
 EXISTS(SELECT 1 FROM rticore_gl_journals j WHERE j.tenant_id=NEW.tenant_id AND j.period_id=NEW.period_id AND j.status IN ('draft','approved')) OR
 (SELECT coalesce(sum(l.debit_cents),0) FROM rticore_gl_lines l JOIN rticore_gl_journals j ON j.tenant_id=l.tenant_id AND j.id=l.journal_id
 WHERE j.tenant_id=NEW.tenant_id AND j.period_id=NEW.period_id AND j.status='posted')!=NEW.snapshot_debits OR
 (SELECT coalesce(sum(l.credit_cents),0) FROM rticore_gl_lines l JOIN rticore_gl_journals j ON j.tenant_id=l.tenant_id AND j.id=l.journal_id
 WHERE j.tenant_id=NEW.tenant_id AND j.period_id=NEW.period_id AND j.status='posted')!=NEW.snapshot_credits OR
 NEW.snapshot_debits!=NEW.snapshot_credits
 THEN rticore_raise('GL_CLOSE_RECONCILIATION') END;
    UPDATE rticore_gl_periods SET status='closed' WHERE tenant_id=NEW.tenant_id AND id=NEW.period_id AND status='open';
    GET DIAGNOSTICS _rc = ROW_COUNT;
    PERFORM CASE WHEN _rc!=1 THEN rticore_raise('GL_CLOSE_CONFLICT') END;
  END IF;
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_gl_close_apply ON rticore_gl_close_requests;
CREATE TRIGGER rticore_gl_close_apply AFTER UPDATE OF status ON rticore_gl_close_requests FOR EACH ROW EXECUTE FUNCTION rticore_gl_close_apply_fn();

