-- rticore_gl_close_review: BEFORE UPDATE ON rticore_gl_close_requests
CREATE OR REPLACE FUNCTION rticore_gl_close_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.status!='pending' OR NEW.status NOT IN ('approved','rejected') OR NEW.version!=OLD.version+1
 OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.period_id IS DISTINCT FROM OLD.period_id
 OR NEW.notes IS DISTINCT FROM OLD.notes OR NEW.snapshot_debits IS DISTINCT FROM OLD.snapshot_debits
 OR NEW.snapshot_credits IS DISTINCT FROM OLD.snapshot_credits OR NEW.created_by IS DISTINCT FROM OLD.created_by
 OR NEW.legal_entity_id IS DISTINCT FROM OLD.legal_entity_id OR NEW.requested_by IS DISTINCT FROM OLD.requested_by
 OR NEW.reason IS DISTINCT FROM OLD.reason OR NEW.created_at IS DISTINCT FROM OLD.created_at
 OR NEW.reviewed_by IS NULL OR coalesce(length(NEW.review_notes),0)<12
 OR lower(NEW.reviewed_by)=lower(coalesce(OLD.created_by,OLD.requested_by))) THEN
    PERFORM rticore_raise('GL_CLOSE_IMMUTABLE');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_gl_close_review ON rticore_gl_close_requests;
CREATE TRIGGER rticore_gl_close_review BEFORE UPDATE ON rticore_gl_close_requests FOR EACH ROW EXECUTE FUNCTION rticore_gl_close_review_fn();

