-- rticore_gl_journal_review: BEFORE UPDATE ON rticore_gl_journals
CREATE OR REPLACE FUNCTION rticore_gl_journal_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
 OR NEW.legal_entity_id IS DISTINCT FROM OLD.legal_entity_id OR NEW.period_id IS DISTINCT FROM OLD.period_id
 OR NEW.source_key IS DISTINCT FROM OLD.source_key OR NEW.source_type IS DISTINCT FROM OLD.source_type
 OR NEW.memo IS DISTINCT FROM OLD.memo OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at IS DISTINCT FROM OLD.created_at
 OR NEW.version!=OLD.version+1 OR NOT (
 (OLD.status='draft' AND NEW.status IN ('approved','rejected'))
 OR (OLD.status='approved' AND NEW.status='posted')
 ) THEN rticore_raise('GL_JOURNAL_IMMUTABLE') END;
    PERFORM CASE WHEN NEW.status IN ('approved','posted') AND NOT EXISTS (
 SELECT 1 FROM rticore_gl_periods p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.period_id
 AND p.legal_entity_id=NEW.legal_entity_id AND p.status='open'
 ) THEN rticore_raise('GL_PERIOD_CLOSED') END;
    PERFORM CASE WHEN NEW.status='approved' AND (
 (SELECT count(*) FROM rticore_gl_lines WHERE journal_id=NEW.id AND tenant_id=NEW.tenant_id)<2 OR
 (SELECT coalesce(sum(debit_cents),0) FROM rticore_gl_lines WHERE journal_id=NEW.id AND tenant_id=NEW.tenant_id)!=
 (SELECT coalesce(sum(credit_cents),0) FROM rticore_gl_lines WHERE journal_id=NEW.id AND tenant_id=NEW.tenant_id)
 ) THEN rticore_raise('GL_UNBALANCED') END;
    PERFORM CASE WHEN NEW.status='posted' AND NEW.reviewed_by IS NULL THEN rticore_raise('GL_UNAPPROVED') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_gl_journal_review ON rticore_gl_journals;
CREATE TRIGGER rticore_gl_journal_review BEFORE UPDATE ON rticore_gl_journals FOR EACH ROW EXECUTE FUNCTION rticore_gl_journal_review_fn();

