-- rticore_gl_reversal_exact: BEFORE INSERT ON rticore_gl_reversal_links
CREATE OR REPLACE FUNCTION rticore_gl_reversal_exact_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NOT EXISTS(
 SELECT 1 FROM rticore_gl_journals a JOIN rticore_gl_journals b
 ON a.tenant_id=b.tenant_id AND a.legal_entity_id=b.legal_entity_id
 WHERE a.id=NEW.original_journal_id AND b.id=NEW.reversal_journal_id AND a.tenant_id=NEW.tenant_id
 AND a.status='posted' AND b.status='draft' AND b.source_type='reversal'
 AND b.source_key=a.id AND
 (SELECT count(*) FROM rticore_gl_lines WHERE tenant_id=NEW.tenant_id AND journal_id=b.id)>=2
 AND NOT EXISTS(
 SELECT 1 FROM (
 SELECT account_id,sum(debit_cents) d,sum(credit_cents) c FROM rticore_gl_lines
 WHERE tenant_id=NEW.tenant_id AND journal_id=a.id GROUP BY account_id
 ) x LEFT JOIN (
 SELECT account_id,sum(debit_cents) d,sum(credit_cents) c FROM rticore_gl_lines
 WHERE tenant_id=NEW.tenant_id AND journal_id=b.id GROUP BY account_id
 ) y ON x.account_id=y.account_id
 WHERE y.account_id IS NULL OR x.d!=y.c OR x.c!=y.d
 )
 AND (SELECT count(DISTINCT account_id) FROM rticore_gl_lines WHERE tenant_id=NEW.tenant_id AND journal_id=a.id)=
 (SELECT count(DISTINCT account_id) FROM rticore_gl_lines WHERE tenant_id=NEW.tenant_id AND journal_id=b.id)
)) THEN
    PERFORM rticore_raise('GL_REVERSAL_NOT_EXACT');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_gl_reversal_exact ON rticore_gl_reversal_links;
CREATE TRIGGER rticore_gl_reversal_exact BEFORE INSERT ON rticore_gl_reversal_links FOR EACH ROW EXECUTE FUNCTION rticore_gl_reversal_exact_fn();

