CREATE OR REPLACE FUNCTION rticore_hr_employee_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.email IS DISTINCT FROM OLD.email
 OR NEW.employment_type IS DISTINCT FROM OLD.employment_type OR NEW.start_date IS DISTINCT FROM OLD.start_date
 OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at IS DISTINCT FROM OLD.created_at
 OR NEW.version!=OLD.version+1 OR NOT (
 (OLD.status='onboarding' AND NEW.status='active') OR
 (OLD.status='active' AND NEW.status='offboarded')
 )
 OR NEW.approved_by IS NULL OR lower(NEW.approved_by)=lower(OLD.created_by)
 OR lower(NEW.approved_by)=lower(OLD.email) OR coalesce(length(NEW.reason),0)<12) THEN
    PERFORM rticore_raise('HR_LIFECYCLE_IMMUTABLE');
  END IF;
  RETURN NEW;
END
$fn$;
