CREATE OR REPLACE FUNCTION rticore_hr_leave_policy_approve_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.status!='draft' OR NEW.status!='approved' OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
 OR NEW.legal_entity_id IS DISTINCT FROM OLD.legal_entity_id OR NEW.leave_type IS DISTINCT FROM OLD.leave_type
 OR NEW.calendar_year IS DISTINCT FROM OLD.calendar_year OR NEW.days_entitlement IS DISTINCT FROM OLD.days_entitlement
 OR NEW.created_by IS DISTINCT FROM OLD.created_by OR lower(NEW.approved_by)=lower(OLD.created_by)) THEN
    PERFORM rticore_raise('HR_POLICY_IMMUTABLE');
  END IF;
  RETURN NEW;
END
$fn$;
