-- rticore_hr_leave_review: BEFORE UPDATE ON rticore_hr_leave_requests
CREATE OR REPLACE FUNCTION rticore_hr_leave_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN OLD.status!='draft' OR NEW.status NOT IN ('approved','rejected') OR NEW.version!=OLD.version+1
 OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.id IS DISTINCT FROM OLD.id OR NEW.email IS DISTINCT FROM OLD.email
 OR NEW.policy_id IS DISTINCT FROM OLD.policy_id OR NEW.from_date IS DISTINCT FROM OLD.from_date
 OR NEW.to_date IS DISTINCT FROM OLD.to_date OR NEW.business_days IS DISTINCT FROM OLD.business_days
 OR NEW.created_by IS DISTINCT FROM OLD.created_by OR lower(NEW.reviewed_by)=lower(OLD.created_by)
 OR lower(NEW.reviewed_by)=lower(OLD.email) THEN rticore_raise('HR_LEAVE_IMMUTABLE') END;
    PERFORM CASE WHEN NEW.status='approved' AND NOT EXISTS(
 SELECT 1 FROM rticore_hr_employees e JOIN rticore_erp_staff_org s ON s.email=e.email AND s.tenant_id=e.tenant_id AND s.status='approved'
 JOIN rticore_erp_org_units u ON u.id=s.unit_id AND u.tenant_id=s.tenant_id
 JOIN rticore_hr_leave_policies p ON p.tenant_id=e.tenant_id AND p.id=NEW.policy_id AND p.status='approved'
 WHERE e.tenant_id=NEW.tenant_id AND e.email=NEW.email AND e.status='active'
 AND strftime('%Y',NEW.from_date)=cast(p.calendar_year as text) AND strftime('%Y',NEW.to_date)=cast(p.calendar_year as text)
 AND (u.id=p.legal_entity_id OR EXISTS(
 WITH RECURSIVE anc(id,parent_id) AS (SELECT id,parent_id FROM rticore_erp_org_units WHERE tenant_id=NEW.tenant_id AND id=u.id
 UNION ALL SELECT x.id,x.parent_id FROM rticore_erp_org_units x JOIN anc a ON x.id=a.parent_id WHERE x.tenant_id=NEW.tenant_id)
 SELECT 1 FROM anc WHERE id=p.legal_entity_id))
 AND (SELECT coalesce(sum(r.business_days),0) FROM rticore_hr_leave_requests r
 WHERE r.tenant_id=NEW.tenant_id AND r.email=NEW.email AND r.policy_id=NEW.policy_id AND r.status='approved')+NEW.business_days<=p.days_entitlement
 AND NOT EXISTS(SELECT 1 FROM rticore_hr_leave_requests r WHERE r.tenant_id=NEW.tenant_id AND r.email=NEW.email AND r.status='approved' AND r.id!=NEW.id AND r.from_date<=NEW.to_date AND r.to_date>=NEW.from_date)
 ) THEN rticore_raise('HR_LEAVE_BALANCE_OR_OVERLAP') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_hr_leave_review ON rticore_hr_leave_requests;
CREATE TRIGGER rticore_hr_leave_review BEFORE UPDATE ON rticore_hr_leave_requests FOR EACH ROW EXECUTE FUNCTION rticore_hr_leave_review_fn();

-- rticore_invoice_approve: BEFORE UPDATE OF status ON rticore_billing_invoices
CREATE OR REPLACE FUNCTION rticore_invoice_approve_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='approved') THEN
    PERFORM CASE WHEN NOT EXISTS(SELECT 1 FROM rticore_delivery_projects p JOIN rticore_delivery_milestones m ON m.project_id=p.id AND m.tenant_id=p.tenant_id WHERE p.id=NEW.project_id AND p.tenant_id=NEW.tenant_id AND m.id=NEW.milestone_id AND m.status='accepted'
 AND (SELECT coalesce(sum(i.amount_cents),0) FROM rticore_billing_invoices i WHERE i.tenant_id=p.tenant_id AND i.project_id=p.id AND i.status='approved')+NEW.amount_cents<=p.contract_cents
 AND (SELECT coalesce(sum(i.amount_cents),0) FROM rticore_billing_invoices i WHERE i.milestone_id=m.id AND i.status='approved')+NEW.amount_cents<=m.amount_cents)
 THEN rticore_raise('DELIVERY_CONFLICT: invoice exceeds accepted milestone or PO') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_invoice_approve ON rticore_billing_invoices;
CREATE TRIGGER rticore_invoice_approve BEFORE UPDATE OF status ON rticore_billing_invoices FOR EACH ROW EXECUTE FUNCTION rticore_invoice_approve_fn();

