-- rticore_lead_reactivated_sla: AFTER UPDATE OF status ON rticore_marketing_leads
CREATE OR REPLACE FUNCTION rticore_lead_reactivated_sla_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.status='disqualified' AND NEW.status IN ('new','assigned')) THEN
    INSERT INTO rticore_lead_sla_history(id,tenant_id,lead_id,snapshot_json)
 SELECT lower(hex(randomblob(16))),tenant_id,lead_id,jsonb_build_object('owner_email',owner_email,'assigned_at',assigned_at,'response_due_at',response_due_at,'first_response_at',first_response_at,'baseline',baseline)
 FROM rticore_sales_lead_sla WHERE tenant_id=NEW.tenant_id AND lead_id=NEW.id;
    UPDATE rticore_sales_lead_sla SET owner_email=NEW.assigned_sales_email,first_response_at=NULL,baseline='new',assigned_at=strftime('%Y-%m-%dT%H:%M:%SZ','now'),
 response_due_at=strftime('%Y-%m-%dT%H:%M:%SZ','now',printf('+%d minutes',coalesce((SELECT lead_response_minutes FROM rticore_sales_activity_policy WHERE tenant_id=NEW.tenant_id),120)))
 WHERE tenant_id=NEW.tenant_id AND lead_id=NEW.id;
  END IF;
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_lead_reactivated_sla ON rticore_marketing_leads;
CREATE TRIGGER rticore_lead_reactivated_sla AFTER UPDATE OF status ON rticore_marketing_leads FOR EACH ROW EXECUTE FUNCTION rticore_lead_reactivated_sla_fn();

