 VALUES(NEW.tenant_id,NEW.id,NEW.assigned_sales_email,strftime('%Y-%m-%dT%H:%M:%SZ','now'),
 strftime('%Y-%m-%dT%H:%M:%SZ','now',printf('+%d minutes',coalesce((SELECT lead_response_minutes FROM rticore_sales_activity_policy WHERE tenant_id=NEW.tenant_id),120)))) ON CONFLICT DO NOTHING;
