CREATE OR REPLACE FUNCTION rticore_lead_sla_reassigned_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.assigned_sales_email<>OLD.assigned_sales_email) THEN
    UPDATE rticore_sales_lead_sla SET owner_email=NEW.assigned_sales_email,
 assigned_at=CASE WHEN first_response_at IS NULL THEN strftime('%Y-%m-%dT%H:%M:%SZ','now') ELSE assigned_at END,
 response_due_at=CASE WHEN first_response_at IS NULL THEN strftime('%Y-%m-%dT%H:%M:%SZ','now',printf('+%d minutes',coalesce((SELECT lead_response_minutes FROM rticore_sales_activity_policy WHERE tenant_id=NEW.tenant_id),120))) ELSE response_due_at END
 WHERE tenant_id=NEW.tenant_id AND lead_id=NEW.id;
  END IF;
  RETURN NULL;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_lead_sla_reassigned ON rticore_marketing_leads;
