BEGIN
  IF (NEW.communication_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM rticore_opportunity_emails e WHERE e.id=NEW.communication_id
 AND e.tenant_id=NEW.tenant_id AND e.opportunity_id=NEW.opportunity_id AND e.direction='inbound' AND (e.release_id IS NULL OR e.release_id=NEW.release_id))) THEN
    PERFORM rticore_raise('FLOW_CONFLICT: email must belong to the same opportunity and release');
