-- rticore_partner_snapshot_no_update: BEFORE UPDATE ON rticore_partner_records
CREATE OR REPLACE FUNCTION rticore_partner_snapshot_no_update_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.tenant_id!=OLD.tenant_id OR NEW.kind!=OLD.kind OR NEW.vendor_id!=OLD.vendor_id OR NEW.opportunity_id IS DISTINCT FROM OLD.opportunity_id
 OR NEW.offer_id IS DISTINCT FROM OLD.offer_id OR NEW.document_id IS DISTINCT FROM OLD.document_id OR NEW.title!=OLD.title OR NEW.created_by!=OLD.created_by
 OR NEW.version!=OLD.version+1
 OR (NEW.data_json!=OLD.data_json AND NOT(OLD.kind='purchase' AND OLD.status='ordered' AND NEW.status IN ('ordered','received')
 AND json_remove(NEW.data_json,'$.received_quantity','$.received_date')=json_remove(OLD.data_json,'$.received_quantity','$.received_date')
 AND json_extract(NEW.data_json,'$.received_quantity')>json_extract(OLD.data_json,'$.received_quantity')
 AND json_extract(NEW.data_json,'$.received_quantity')<=json_extract(OLD.data_json,'$.quantity')))) THEN
    PERFORM rticore_raise('PARTNER_IMMUTABLE');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_partner_snapshot_no_update ON rticore_partner_records;
CREATE TRIGGER rticore_partner_snapshot_no_update BEFORE UPDATE ON rticore_partner_records FOR EACH ROW EXECUTE FUNCTION rticore_partner_snapshot_no_update_fn();

-- rticore_payment_approve: BEFORE UPDATE OF status ON rticore_billing_payments
CREATE OR REPLACE FUNCTION rticore_payment_approve_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='approved') THEN
    PERFORM CASE WHEN NOT EXISTS(SELECT 1 FROM rticore_billing_invoices i WHERE i.tenant_id=NEW.tenant_id AND i.id=NEW.invoice_id AND i.status='approved' AND NEW.payment_date>=i.issue_date
 AND (SELECT coalesce(sum(p.amount_cents),0) FROM rticore_billing_payments p WHERE p.invoice_id=i.id AND p.status='approved')+NEW.amount_cents BETWEEN 0 AND i.amount_cents+i.vat_cents)
 THEN rticore_raise('DELIVERY_CONFLICT: payment exceeds outstanding') END;
    PERFORM CASE WHEN NEW.reversal_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM rticore_billing_payments p WHERE p.id=NEW.reversal_of AND p.invoice_id=NEW.invoice_id AND p.tenant_id=NEW.tenant_id AND p.status='approved' AND p.reversal_of IS NULL AND p.amount_cents=-NEW.amount_cents AND NEW.payment_date>=p.payment_date)
 THEN rticore_raise('DELIVERY_CONFLICT: exact approved reversal required') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_payment_approve ON rticore_billing_payments;
CREATE TRIGGER rticore_payment_approve BEFORE UPDATE OF status ON rticore_billing_payments FOR EACH ROW EXECUTE FUNCTION rticore_payment_approve_fn();

