-- rticore_po_review: BEFORE UPDATE ON rticore_purchase_orders
CREATE OR REPLACE FUNCTION rticore_po_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN OLD.status!='draft' OR NEW.status NOT IN ('approved','rejected') OR NEW.version!=OLD.version+1
 OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.vendor_id IS DISTINCT FROM OLD.vendor_id
 OR NEW.offer_id IS DISTINCT FROM OLD.offer_id OR NEW.opportunity_id IS DISTINCT FROM OLD.opportunity_id
 OR NEW.po_number IS DISTINCT FROM OLD.po_number OR NEW.qty IS DISTINCT FROM OLD.qty OR NEW.unit_price_cents IS DISTINCT FROM OLD.unit_price_cents
 OR NEW.created_by IS DISTINCT FROM OLD.created_by OR lower(NEW.reviewed_by)=lower(OLD.created_by)
 THEN rticore_raise('PO_IMMUTABLE') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_po_review ON rticore_purchase_orders;
CREATE TRIGGER rticore_po_review BEFORE UPDATE ON rticore_purchase_orders FOR EACH ROW EXECUTE FUNCTION rticore_po_review_fn();

-- rticore_po_source: BEFORE INSERT ON rticore_purchase_orders
CREATE OR REPLACE FUNCTION rticore_po_source_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM rticore_vendor_offers o JOIN rticore_vendors v
 ON v.tenant_id=o.tenant_id AND v.id=o.vendor_id
 WHERE o.tenant_id=NEW.tenant_id AND o.id=NEW.offer_id AND o.vendor_id=NEW.vendor_id AND o.opportunity_id=NEW.opportunity_id
 AND o.status='validated' AND v.status='validated' AND o.valid_until>=rticore_date_text('now') AND v.valid_until>=rticore_date_text('now')
 AND o.quantity>=NEW.qty AND abs(o.unit_price_idr*100-NEW.unit_price_cents)<1)) THEN
    PERFORM rticore_raise('PO_SOURCE_INVALID');
  END IF;
  RETURN NEW;
END
$fn$;
