CREATE OR REPLACE FUNCTION rticore_proc_budget_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (OLD.status!='draft' OR NEW.status!='approved' OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
 OR NEW.legal_entity_id IS DISTINCT FROM OLD.legal_entity_id OR NEW.period IS DISTINCT FROM OLD.period
 OR NEW.code IS DISTINCT FROM OLD.code OR NEW.limit_cents IS DISTINCT FROM OLD.limit_cents OR NEW.created_by IS DISTINCT FROM OLD.created_by
 OR lower(NEW.approved_by)=lower(OLD.created_by)) THEN
    PERFORM rticore_raise('BUDGET_IMMUTABLE');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_proc_budget_review ON rticore_procurement_budgets;
