-- rticore_proc_commitment_validate: BEFORE INSERT ON rticore_procurement_commitments
CREATE OR REPLACE FUNCTION rticore_proc_commitment_validate_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM rticore_procurement_requisitions r
 JOIN rticore_purchase_orders p ON p.tenant_id=r.tenant_id AND p.opportunity_id=r.opportunity_id
 JOIN rticore_procurement_budgets b ON b.tenant_id=r.tenant_id AND b.id=r.budget_id
 WHERE r.tenant_id=NEW.tenant_id AND r.id=NEW.requisition_id AND r.status='approved' AND p.id=NEW.po_id
 AND p.qty<=r.qty AND p.qty*p.unit_price_cents<=r.ceiling_cents
 AND (SELECT coalesce(sum(pr.ceiling_cents),0) FROM rticore_procurement_requisitions pr
 JOIN rticore_procurement_commitments cm ON cm.tenant_id=pr.tenant_id AND cm.requisition_id=pr.id
 WHERE pr.tenant_id=r.tenant_id AND pr.budget_id=r.budget_id)+r.ceiling_cents<=b.limit_cents)) THEN
    PERFORM rticore_raise('P2P_COMMITMENT_BUDGET');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_proc_commitment_validate ON rticore_procurement_commitments;
CREATE TRIGGER rticore_proc_commitment_validate BEFORE INSERT ON rticore_procurement_commitments FOR EACH ROW EXECUTE FUNCTION rticore_proc_commitment_validate_fn();

