 OR NEW.budget_id IS DISTINCT FROM OLD.budget_id OR NEW.qty IS DISTINCT FROM OLD.qty OR NEW.ceiling_cents IS DISTINCT FROM OLD.ceiling_cents
 OR NEW.request_number IS DISTINCT FROM OLD.request_number OR NEW.title IS DISTINCT FROM OLD.title
 OR NEW.created_by IS DISTINCT FROM OLD.created_by OR lower(NEW.reviewed_by)=lower(OLD.created_by)) THEN
