BEGIN
  IF (NOT EXISTS(SELECT 1 FROM rticore_purchase_orders p WHERE p.id=NEW.po_id AND p.tenant_id=NEW.tenant_id
 AND p.status='approved' AND lower(p.created_by)!=lower(NEW.received_by)
 AND (SELECT coalesce(sum(qty),0) FROM rticore_purchase_receipts r WHERE r.po_id=p.id AND r.tenant_id=p.tenant_id)+NEW.qty<=p.qty)) THEN
    PERFORM rticore_raise('PO_OVER_RECEIPT');
  END IF;
  RETURN NEW;
END
