-- rticore_revenue_approve: BEFORE UPDATE OF status ON rticore_sales_revenue
CREATE OR REPLACE FUNCTION rticore_revenue_approve_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='approved') THEN
    PERFORM CASE WHEN NOT EXISTS(SELECT 1 FROM rticore_sales_opportunities d JOIN rticore_sales_po_checks p ON p.tenant_id=d.tenant_id AND p.opportunity_id=d.id
 JOIN rticore_sales_releases r ON r.id=p.release_id AND r.status='approved' JOIN rticore_sales_award_documents a ON a.id=p.award_id AND a.release_id=r.id
 WHERE d.id=NEW.opportunity_id AND d.tenant_id=NEW.tenant_id AND d.stage='closed_won' AND r.id=NEW.release_id
 AND a.finance_reviewed_by IS NOT NULL AND a.legal_reviewed_by IS NOT NULL AND lower(a.finance_reviewed_by)!=lower(a.legal_reviewed_by)
 AND (SELECT coalesce(sum(x.amount_before_vat),0) FROM rticore_sales_revenue x WHERE x.tenant_id=NEW.tenant_id AND x.opportunity_id=NEW.opportunity_id AND x.status='approved')+NEW.amount_before_vat BETWEEN 0 AND p.po_amount_before_vat+0.001)
 THEN rticore_raise('REVENUE_CONFLICT: verified Closed Won PO required; cumulative recognition exceeds PO') END;
    PERFORM CASE WHEN NEW.reversal_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM rticore_sales_revenue x WHERE x.id=NEW.reversal_of
 AND x.tenant_id=NEW.tenant_id AND x.opportunity_id=NEW.opportunity_id AND x.release_id=NEW.release_id AND x.status='approved'
 AND x.reversal_of IS NULL AND abs(x.amount_before_vat+NEW.amount_before_vat)<0.001)
 THEN rticore_raise('REVENUE_CONFLICT: reversal must exactly offset its approved source') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_revenue_approve ON rticore_sales_revenue;
CREATE TRIGGER rticore_revenue_approve BEFORE UPDATE OF status ON rticore_sales_revenue FOR EACH ROW EXECUTE FUNCTION rticore_revenue_approve_fn();

