BEGIN
  IF (NOT EXISTS(SELECT 1 FROM rticore_security_connectors k JOIN rticore_cyber_cases c
 ON c.tenant_id=k.tenant_id
 JOIN rticore_erp_project_scopes s ON s.tenant_id=c.tenant_id AND s.project_id=c.project_id
