-- rticore_security_dispatch_update: BEFORE UPDATE ON rticore_security_dispatches
CREATE OR REPLACE FUNCTION rticore_security_dispatch_update_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
 OR NEW.connector_id IS DISTINCT FROM OLD.connector_id OR NEW.case_id IS DISTINCT FROM OLD.case_id
 OR NEW.requested_by IS DISTINCT FROM OLD.requested_by OR NEW.created_at IS DISTINCT FROM OLD.created_at
 OR NOT(
 (OLD.status IN ('pending','retryable') AND NEW.status='sending' AND NEW.attempts=OLD.attempts+1 AND OLD.attempts<5)
 OR (OLD.status='sending' AND NEW.status='sending' AND NEW.attempts=OLD.attempts+1 AND OLD.attempts<5
 AND OLD.last_attempt_at<=datetime('now','-15 minutes'))
 OR (OLD.status='sending' AND NEW.status IN ('retryable','delivered','rejected') AND NEW.attempts=OLD.attempts)
 )) THEN
    PERFORM rticore_raise('DISPATCH_IMMUTABLE');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_security_dispatch_update ON rticore_security_dispatches;
CREATE TRIGGER rticore_security_dispatch_update BEFORE UPDATE ON rticore_security_dispatches FOR EACH ROW EXECUTE FUNCTION rticore_security_dispatch_update_fn();

