-- rticore_tender_matrix_gate: BEFORE UPDATE OF stage ON rticore_sales_opportunities
CREATE OR REPLACE FUNCTION rticore_tender_matrix_gate_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.stage!=OLD.stage AND NEW.stage IN ('commercial_review','quotation_sent','negotiation','pending_po','closed_won')
 AND (EXISTS(SELECT 1 FROM rticore_sales_bids b WHERE b.tenant_id=NEW.tenant_id AND b.opportunity_id=NEW.id AND b.channel!='direct')
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%tender%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfp%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfq%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%lpse%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%spse%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%pengadaan%')) THEN
    PERFORM CASE WHEN NOT EXISTS(SELECT 1 FROM rticore_sales_requirements r WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id
 AND r.kind IN ('rks','kak','rfp','rfq') AND r.status='reviewed' AND r.compliance_status='compliant'
 AND EXISTS(SELECT 1 FROM rticore_tender_compliance_items c WHERE c.requirement_id=r.id AND c.mandatory=1)
 AND NOT EXISTS(SELECT 1 FROM rticore_tender_compliance_gaps c WHERE c.requirement_id=r.id AND c.mandatory=1 AND c.is_gap=1))
 THEN rticore_raise('COMPLIANCE_CONFLICT: reviewed clause matrix and current vendor validation required') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_tender_matrix_gate ON rticore_sales_opportunities;
CREATE TRIGGER rticore_tender_matrix_gate BEFORE UPDATE OF stage ON rticore_sales_opportunities FOR EACH ROW EXECUTE FUNCTION rticore_tender_matrix_gate_fn();

-- rticore_tender_package_stage_gate: BEFORE UPDATE OF stage ON rticore_sales_opportunities
CREATE OR REPLACE FUNCTION rticore_tender_package_stage_gate_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.stage!=OLD.stage AND NEW.stage IN ('commercial_review','quotation_sent','negotiation','pending_po','closed_won')
 AND (EXISTS(SELECT 1 FROM rticore_sales_bids b WHERE b.tenant_id=NEW.tenant_id AND b.opportunity_id=NEW.id AND b.channel!='direct')
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%tender%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfp%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfq%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%lpse%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%spse%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%pengadaan%')) THEN
    PERFORM CASE WHEN NOT EXISTS(
 SELECT 1 FROM rticore_tender_deadlines t WHERE t.tenant_id=NEW.tenant_id AND t.opportunity_id=NEW.id
 AND t.milestone='submission' AND t.status='approved' AND datetime(t.due_at)>datetime('now')

 AND EXISTS(SELECT 1 FROM rticore_sales_bids b WHERE b.tenant_id=NEW.tenant_id AND b.opportunity_id=NEW.id AND b.bid_decision='go' AND b.decided_by IS NOT NULL)
 AND EXISTS(SELECT 1 FROM rticore_sales_requirements r WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id AND r.kind IN ('rks','kak','rfp','rfq'))
 AND NOT EXISTS(SELECT 1 FROM rticore_sales_requirements r WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id AND r.kind IN ('rks','kak','rfp','rfq')
 AND (r.status!='reviewed' OR r.compliance_status!='compliant' OR r.reviewed_by IS NULL OR length(r.file_reference)=0 OR length(r.source_content_hash)!=64
 OR NOT EXISTS(SELECT 1 FROM rticore_tender_compliance_items c WHERE c.requirement_id=r.id AND c.mandatory=1)
 OR EXISTS(SELECT 1 FROM rticore_tender_compliance_gaps c WHERE c.requirement_id=r.id AND c.mandatory=1 AND c.is_gap=1)))
 AND (SELECT count(DISTINCT category) FROM rticore_tender_checklist c WHERE c.tenant_id=NEW.tenant_id
 AND c.opportunity_id=NEW.id AND c.mandatory=1)=3
 AND NOT EXISTS(SELECT 1 FROM rticore_tender_checklist c WHERE c.tenant_id=NEW.tenant_id
 AND c.opportunity_id=NEW.id AND c.mandatory=1 AND
 (c.status!='ready' OR length(c.evidence_reference)<8 OR length(c.evidence_sha256)!=64
 OR c.checked_by IS NULL OR lower(c.checked_by)=lower(c.created_by)
 OR (c.due_at IS NOT NULL AND datetime(c.due_at)<datetime('now'))))
 ) THEN rticore_raise('READINESS_CONFLICT: submission deadline and mandatory bid package must be reviewed') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_tender_package_stage_gate ON rticore_sales_opportunities;
CREATE TRIGGER rticore_tender_package_stage_gate BEFORE UPDATE OF stage ON rticore_sales_opportunities FOR EACH ROW EXECUTE FUNCTION rticore_tender_package_stage_gate_fn();

