CREATE OR REPLACE FUNCTION rticore_tender_vault_requirement_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='reviewed' AND NEW.compliance_status='compliant'
 AND NEW.kind IN ('rks','kak','rfp','rfq')
 AND NOT EXISTS(
  SELECT 1 FROM rticore_tender_vault_originals v
  WHERE v.tenant_id=NEW.tenant_id AND v.opportunity_id=NEW.opportunity_id
   AND v.evidence_reference=NEW.file_reference AND v.sha256=NEW.source_content_hash
