-- rticore_tender_vault_stage: BEFORE UPDATE OF stage ON rticore_sales_opportunities
CREATE OR REPLACE FUNCTION rticore_tender_vault_stage_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.stage!=OLD.stage
 AND NEW.stage IN ('commercial_review','quotation_sent','negotiation','pending_po','closed_won')
 AND (EXISTS(SELECT 1 FROM rticore_sales_bids b WHERE b.tenant_id=NEW.tenant_id AND b.opportunity_id=NEW.id AND b.channel!='direct')
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%tender%'
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfp%'
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfq%'
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%lpse%'
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%spse%'
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%pengadaan%')
 AND (
   EXISTS(SELECT 1 FROM rticore_tender_checklist c
          WHERE c.tenant_id=NEW.tenant_id AND c.opportunity_id=NEW.id AND c.mandatory=1
           AND NOT EXISTS(SELECT 1 FROM rticore_tender_vault_originals v
             WHERE v.tenant_id=c.tenant_id AND v.opportunity_id=c.opportunity_id
             AND v.evidence_reference=c.evidence_reference AND v.sha256=c.evidence_sha256 AND v.file_name=c.document_name))
   OR EXISTS(SELECT 1 FROM rticore_sales_requirements r
          WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id AND r.kind IN ('rks','kak','rfp','rfq')
           AND NOT EXISTS(SELECT 1 FROM rticore_tender_vault_originals v
             WHERE v.tenant_id=r.tenant_id AND v.opportunity_id=r.opportunity_id
             AND v.evidence_reference=r.file_reference AND v.sha256=r.source_content_hash
             AND v.kind=CASE WHEN r.kind IN ('rks','kak') THEN r.kind ELSE 'supporting' END))
   OR EXISTS(SELECT 1 FROM rticore_tender_compliance_items c
          WHERE c.tenant_id=NEW.tenant_id AND c.opportunity_id=NEW.id AND c.mandatory=1
           AND NOT EXISTS(SELECT 1 FROM rticore_tender_vault_originals v
             WHERE v.tenant_id=c.tenant_id AND v.opportunity_id=c.opportunity_id
             AND v.evidence_reference=c.evidence_reference AND v.sha256=c.evidence_sha256))
 )) THEN
    PERFORM rticore_raise('TENDER_VAULT_EVIDENCE: tender originals are missing or mismatched');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_tender_vault_stage ON rticore_sales_opportunities;
CREATE TRIGGER rticore_tender_vault_stage BEFORE UPDATE OF stage ON rticore_sales_opportunities FOR EACH ROW EXECUTE FUNCTION rticore_tender_vault_stage_fn();

-- rticore_timesheet_capacity: BEFORE INSERT ON rticore_project_timesheets
CREATE OR REPLACE FUNCTION rticore_timesheet_capacity_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN NOT EXISTS (
    SELECT 1 FROM rticore_delivery_projects p
    JOIN rticore_resource_allocations a ON a.tenant_id=p.tenant_id AND a.opportunity_id=p.opportunity_id AND a.id=NEW.allocation_id
    JOIN rticore_resource_people r ON r.tenant_id=a.tenant_id AND r.id=a.person_id
    WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.project_id AND p.status='active'
      AND r.id=NEW.person_id AND r.active=1 AND a.status='active'
      AND substr(NEW.work_date,1,7)=a.allocation_month
      AND NEW.work_date BETWEEN p.start_date AND p.end_date
      AND lower(NEW.created_by)=lower(r.email)
      AND NEW.minutes+coalesce((SELECT sum(t.minutes) FROM rticore_project_timesheets t
          WHERE t.tenant_id=NEW.tenant_id AND t.person_id=NEW.person_id AND t.work_date=NEW.work_date AND t.status!='rejected'),0)<=480
      AND NEW.minutes+coalesce((SELECT sum(t.minutes) FROM rticore_project_timesheets t
          WHERE t.tenant_id=NEW.tenant_id AND t.allocation_id=NEW.allocation_id AND t.status!='rejected'),0)<=round(a.person_days*480)
  ) THEN rticore_raise('TIMESHEET_CAPACITY_CONFLICT') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_timesheet_capacity ON rticore_project_timesheets;
CREATE TRIGGER rticore_timesheet_capacity BEFORE INSERT ON rticore_project_timesheets FOR EACH ROW EXECUTE FUNCTION rticore_timesheet_capacity_fn();

