-- rticore_timesheet_review_capacity: BEFORE UPDATE OF status ON rticore_project_timesheets
CREATE OR REPLACE FUNCTION rticore_timesheet_review_capacity_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NEW.status='approved') THEN
    PERFORM CASE WHEN NOT EXISTS (
   SELECT 1 FROM rticore_resource_allocations a JOIN rticore_resource_people r ON r.id=a.person_id AND r.tenant_id=a.tenant_id
   WHERE a.id=NEW.allocation_id AND a.tenant_id=NEW.tenant_id AND a.status='active' AND r.active=1
    AND (SELECT coalesce(sum(t.minutes),0) FROM rticore_project_timesheets t WHERE t.tenant_id=NEW.tenant_id AND t.allocation_id=a.id AND t.status!='rejected')<=round(a.person_days*480)
  ) THEN rticore_raise('TIMESHEET_CAPACITY_CONFLICT') END;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_timesheet_review_capacity ON rticore_project_timesheets;
CREATE TRIGGER rticore_timesheet_review_capacity BEFORE UPDATE OF status ON rticore_project_timesheets FOR EACH ROW EXECUTE FUNCTION rticore_timesheet_review_capacity_fn();

-- rticore_timesheet_transition: BEFORE UPDATE ON rticore_project_timesheets
CREATE OR REPLACE FUNCTION rticore_timesheet_transition_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN OLD.status!='submitted' OR NEW.status NOT IN ('approved','rejected')
   OR NEW.version!=OLD.version+1 OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
   OR NEW.project_id IS DISTINCT FROM OLD.project_id OR NEW.person_id IS DISTINCT FROM OLD.person_id
   OR NEW.allocation_id IS DISTINCT FROM OLD.allocation_id OR NEW.work_date IS DISTINCT FROM OLD.work_date
   OR NEW.minutes IS DISTINCT FROM OLD.minutes OR NEW.billable IS DISTINCT FROM OLD.billable
   OR NEW.cost_snapshot_cents IS DISTINCT FROM OLD.cost_snapshot_cents
   OR NEW.description IS DISTINCT FROM OLD.description OR NEW.created_by IS DISTINCT FROM OLD.created_by
   OR lower(NEW.reviewed_by)=lower(OLD.created_by)
   THEN rticore_raise('TIMESHEET_IMMUTABLE') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_timesheet_transition ON rticore_project_timesheets;
CREATE TRIGGER rticore_timesheet_transition BEFORE UPDATE ON rticore_project_timesheets FOR EACH ROW EXECUTE FUNCTION rticore_timesheet_transition_fn();

