-- rticore_treasury_payment_create: BEFORE INSERT ON rticore_treasury_payments
CREATE OR REPLACE FUNCTION rticore_treasury_payment_create_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM rticore_ap_supplier_invoices i
 JOIN rticore_purchase_orders p ON p.id=i.po_id AND p.tenant_id=i.tenant_id
 JOIN rticore_erp_opportunity_scopes s ON s.opportunity_id=p.opportunity_id AND s.tenant_id=p.tenant_id AND s.status='approved'
 JOIN rticore_treasury_accounts a ON a.tenant_id=s.tenant_id AND a.legal_entity_id=s.legal_entity_id
 WHERE i.tenant_id=NEW.tenant_id AND i.id=NEW.ap_invoice_id AND i.status='approved'
 AND s.legal_entity_id=NEW.legal_entity_id AND a.id=NEW.bank_account_id AND a.active=1
 AND (SELECT coalesce(sum(x.amount_cents),0) FROM rticore_treasury_payments x
 WHERE x.tenant_id=NEW.tenant_id AND x.ap_invoice_id=i.id AND x.status!='rejected')+NEW.amount_cents<=i.amount_cents)) THEN
    PERFORM rticore_raise('TREASURY_AP_SCOPE_OR_LIMIT');
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_treasury_payment_create ON rticore_treasury_payments;
CREATE TRIGGER rticore_treasury_payment_create BEFORE INSERT ON rticore_treasury_payments FOR EACH ROW EXECUTE FUNCTION rticore_treasury_payment_create_fn();

