CREATE TRIGGER rticore_treasury_payment_no_delete BEFORE DELETE ON rticore_treasury_payments FOR EACH ROW EXECUTE FUNCTION rticore_treasury_payment_no_delete_fn();

-- rticore_treasury_payment_review: BEFORE UPDATE ON rticore_treasury_payments
CREATE OR REPLACE FUNCTION rticore_treasury_payment_review_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    PERFORM CASE WHEN NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.legal_entity_id IS DISTINCT FROM OLD.legal_entity_id
 OR NEW.ap_invoice_id IS DISTINCT FROM OLD.ap_invoice_id OR NEW.bank_account_id IS DISTINCT FROM OLD.bank_account_id
 OR NEW.amount_cents IS DISTINCT FROM OLD.amount_cents OR NEW.created_by IS DISTINCT FROM OLD.created_by
 OR NEW.version!=OLD.version+1 OR NOT (
 (OLD.status='draft' AND NEW.status IN ('approved','rejected')) OR
 (OLD.status='approved' AND NEW.status='recorded') OR
 (OLD.status='recorded' AND NEW.status='settled')
 ) THEN rticore_raise('TREASURY_IMMUTABLE') END;
    PERFORM CASE WHEN NEW.status='recorded' AND (NEW.recorded_by IS NULL OR lower(NEW.recorded_by)=lower(NEW.created_by)
 OR lower(NEW.recorded_by)=lower(NEW.reviewed_by)) THEN rticore_raise('TREASURY_SOD') END;
    PERFORM CASE WHEN NEW.status='settled' AND (NEW.settled_by IS NULL OR lower(NEW.settled_by)=lower(NEW.recorded_by)) THEN rticore_raise('TREASURY_SOD') END;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_treasury_payment_review ON rticore_treasury_payments;
CREATE TRIGGER rticore_treasury_payment_review BEFORE UPDATE ON rticore_treasury_payments FOR EACH ROW EXECUTE FUNCTION rticore_treasury_payment_review_fn();

-- rticore_vendor_history: BEFORE UPDATE ON rticore_vendors
CREATE OR REPLACE FUNCTION rticore_vendor_history_fn() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE _rc bigint := 0;
BEGIN
    INSERT INTO rticore_procurement_history VALUES(lower(hex(randomblob(16))),OLD.tenant_id,'vendor',OLD.id,jsonb_build_object('legal_name',OLD.legal_name,'registration_number',OLD.registration_number,'contact_email',OLD.contact_email,'capabilities',OLD.capabilities,'capacity_units',OLD.capacity_units,'capacity_unit',OLD.capacity_unit,'evidence_reference',OLD.evidence_reference,'evidence_sha256',OLD.evidence_sha256,'valid_until',OLD.valid_until,'version',OLD.version,'status',OLD.status,'created_by',OLD.created_by,'reviewed_by',OLD.reviewed_by,'review_notes',OLD.review_notes),rticore_now_text());
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS rticore_vendor_history ON rticore_vendors;
CREATE TRIGGER rticore_vendor_history BEFORE UPDATE ON rticore_vendors FOR EACH ROW EXECUTE FUNCTION rticore_vendor_history_fn();

-- Backfill: response SLA for open Leads created before the triggers existed.
INSERT INTO rticore_sales_lead_sla(tenant_id,lead_id,owner_email,assigned_at,response_due_at,baseline)
SELECT l.tenant_id,l.id,l.assigned_sales_email,strftime('%Y-%m-%dT%H:%M:%SZ','now'),
 strftime('%Y-%m-%dT%H:%M:%SZ','now',printf('+%d minutes',coalesce(p.lead_response_minutes,120))),'legacy_unverified'
FROM rticore_marketing_leads l LEFT JOIN rticore_sales_activity_policy p ON p.tenant_id=l.tenant_id
WHERE l.status NOT IN ('converted','disqualified')
ON CONFLICT DO NOTHING;
